(5219029, 759620, 47294, '<td valign="top">Beautiful tonal range here, very nice photo. 7</td>', 'Beautiful tonal range here, very nice photo. 7', '2009-01-26 00:05:28.000000', NULL, 1),
(5219031, 759340, 83313, '<td valign="top">maybe could be a touch brighter on the details of the tree, but otherwise nice.</td>', 'maybe could be a touch brighter on the details of the tree, but otherwise nice.', '2009-01-26 00:05:50.000000', NULL, 1),
