(5219171, 759182, 102024, '<td valign="top">Nice simple composition</td>', 'Nice simple composition', '2009-01-26 00:41:31.000000', NULL, 1),
(5219178, 759187, 47294, '<td valign="top">This comment could be a bit of a personnel taste but this looks a little over=processed.  The trunk of the ghost gum looks a little too green for me.  That being said I love the composition and sublect choice.  I think you''ll receive some comments regarding the horizon even though I''m sure this is a hillside.  Good luck 7</td>', 'This comment could be a bit of a personnel taste but this looks a little over=processed.  The trunk of the ghost gum looks a little too green for me.  That being said I love the composition and sublect choice.  I think you''ll receive some comments regarding the horizon even though I''m sure this is a hillside.  Good luck 7', '2009-01-26 00:45:31.000000', NULL, 1),
(5219185, 759291, 47294, '<td valign="top">Wonderful colours here, I would like to see a bit more of the tree but apart from that, a really good entry - Good luck 8</td>', 'Wonderful colours here, I would like to see a bit more of the tree but apart from that, a really good entry - Good luck 8', '2009-01-26 00:48:17.000000', NULL, 1),
(5219189, 759231, 47294, '<td valign="top">Beautiful Aussie landscape, Good luck mate. 9</td>', 'Beautiful Aussie landscape, Good luck mate. 9', '2009-01-26 00:49:52.000000', NULL, 1),
(5219190, 759187, 96751, '<td valign="top">The colors on this are gorgeous.</td>', 'The colors on this are gorgeous.', '2009-01-26 00:49:52.000000', NULL, 1),
