(5219194, 759251, 54645, '<td valign="top">Beautiful post processing Michelle.  The foreground is stunning, footprints and all. The tree is clean and free from sharpening artifacts. Well done.</td>', 'Beautiful post processing Michelle.  The foreground is stunning, footprints and all. The tree is clean and free from sharpening artifacts. Well done.', '2009-01-26 00:50:54.000000', NULL, 1),
(5219198, 757839, 54645, '<td valign="top">Well done Lydia. Unique take on the topic. I hope it does well.</td>', 'Well done Lydia. Unique take on the topic. I hope it does well.', '2009-01-26 00:52:11.000000', NULL, 1),
(5219199, 758978, 47294, '<td valign="top">Almost surreal.  Beautiful photography. 9</td>', 'Almost surreal.  Beautiful photography. 9', '2009-01-26 00:52:43.000000', NULL, 1),
(5219202, 759044, 54645, '<td valign="top">Nice choice Kim. I really enjoy looking through this photograph.</td>', 'Nice choice Kim. I really enjoy looking through this photograph.', '2009-01-26 00:54:11.000000', NULL, 1),
(5219204, 759446, 47294, '<td valign="top">I''m worried about your horizon.  DPC tends to punish for such situations even if the land did slope, etc.  Nice light and love your use of negative space.  Good luck. 7</td>', 'I''m worried about your horizon.  DPC tends to punish for such situations even if the land did slope, etc.  Nice light and love your use of negative space.  Good luck. 7', '2009-01-26 00:54:16.000000', NULL, 1),
(5219206, 759750, 83313, '<td valign="top">A fascinating place. Looks like the result of a great hike. I hate to be critical of this one, but there is just so much fine detail that the subject does not stand out well.</td>', 'A fascinating place. Looks like the result of a great hike. I hate to be critical of this one, but there is just so much fine detail that the subject does not stand out well.', '2009-01-26 00:54:49.000000', NULL, 1),
(5219212, 759713, 83313, '<td valign="top">I see some heavy graininess in the background that some selective noise reduction could have handled. The image as a whole, though is really nice. It looks to me like a scene out of one of Tim Burton''s animated films.</td>', 'I see some heavy graininess in the background that some selective noise reduction could have handled. The image as a whole, though is really nice. It looks to me like a scene out of one of Tim Burton''s animated films.', '2009-01-26 00:57:24.000000', NULL, 1),
(5219213, 758936, 47294, '<td valign="top">Gorgeous softness.  Perfect composition. I love the silvery highlights in the water.  9.</td>', 'Gorgeous softness.  Perfect composition. I love the silvery highlights in the water.  9.', '2009-01-26 00:58:07.000000', NULL, 1),
(5219216, 759275, 47294, '<td valign="top">The green on the trunk is a little too saturated for my liking.  Reasonable composition and good depth of field.  6.</td>', 'The green on the trunk is a little too saturated for my liking.  Reasonable composition and good depth of field.  6.', '2009-01-26 00:59:20.000000', NULL, 1),
(5219217, 759508, 83313, '<td valign="top">Maybe could use a little more punch, but you may also have been going for a calmer look to this. Really nice. Looks like a dragon rising up.</td>', 'Maybe could use a little more punch, but you may also have been going for a calmer look to this. Really nice. Looks like a dragon rising up.', '2009-01-26 00:59:41.000000', NULL, 1),
(5219221, 759254, 47294, '<td valign="top">The tonal range is good if not a tad too contrasty.  Good composition and nice subject. 6.</td>', 'The tonal range is good if not a tad too contrasty.  Good composition and nice subject. 6.', '2009-01-26 01:01:47.000000', NULL, 1),
(5219223, 759768, 47294, '<td valign="top">Nice tonal range.  Almost Ansell Adams-y :).  Nice subject.  The scrap at the bottom of the tree is annoying, but what can you do....6.</td>', 'Nice tonal range.  Almost Ansell Adams-y :).  Nice subject.  The scrap at the bottom of the tree is annoying, but what can you do....6.', '2009-01-26 01:02:36.000000', NULL, 1),
(5219228, 759566, 47294, '<td valign="top">Your capture looks so peaceful, beautiful capture.  Good luck 8</td>', 'Your capture looks so peaceful, beautiful capture.  Good luck 8', '2009-01-26 01:05:06.000000', NULL, 1),
(5219230, 759433, 47294, '<td valign="top">Beautiful capture, love the red of the trees leaves against the white sky.  Good luck 8</td>', 'Beautiful capture, love the red of the trees leaves against the white sky.  Good luck 8', '2009-01-26 01:06:59.000000', NULL, 1),
(5219232, 759703, 47294, '<td valign="top">Magic photo, almost unreal...I drove for 500 kilometres plus to find such a tree to no avail.  Best of luck in the challenge 9</td>', 'Magic photo, almost unreal...I drove for 500 kilometres plus to find such a tree to no avail.  Best of luck in the challenge 9', '2009-01-26 01:08:21.000000', NULL, 1),
(5219234, 759655, 47294, '<td valign="top">Beautiful processing, so soft and magical! Good luck with the challenge 8</td>', 'Beautiful processing, so soft and magical! Good luck with the challenge 8', '2009-01-26 01:11:32.000000', NULL, 1),
