(5219246, 758065, 39850, '<td valign="top">8 - Beautiful tree, love the contrast against the different trees in the background.  Tones work well.  Like your composition, interesting image - almost looks like an ''overlay'' - a lot to see.</td>', '8 - Beautiful tree, love the contrast against the different trees in the background.  Tones work well.  Like your composition, interesting image - almost looks like an ''overlay'' - a lot to see.', '2009-01-26 01:17:03.000000', NULL, 1),
(5219248, 759628, 47294, '<td valign="top">Looks almost evil, creepy, dark.  Interesting angle and composition, good luck.</td>', 'Looks almost evil, creepy, dark.  Interesting angle and composition, good luck.', '2009-01-26 01:17:34.000000', NULL, 1),
(5219251, 759551, 47294, '<td valign="top">Too good!!!  AMAZING photo, best of luck...I think a ribbon! 9</td>', 'Too good!!!  AMAZING photo, best of luck...I think a ribbon! 9', '2009-01-26 01:19:55.000000', NULL, 1),
