(5219484, 758470, 102811, '<td valign="top">its not the best photo in the world but it made me LMAO (every time I looked at it). For me personally this is what photography is about, capturing the moment or the quirkiness of life. I love it and I hope it ribbons.</td>', 'its not the best photo in the world but it made me LMAO (every time I looked at it). For me personally this is what photography is about, capturing the moment or the quirkiness of life. I love it and I hope it ribbons.', '2009-01-26 04:55:44.000000', NULL, 1),
(5219492, 759764, 47294, '<td valign="top">I like your selection of subject tree, some entries are very uninteresting trees.  I would have preferred a stronger use of the ''rule of 3rds'' and your light is a little off, ie flat.  I can see the trees shadow is long, so you were very close to the right time for perfect light.  On a personal note I would have also liked a bit more saturation in the sky and grass, gold and blue would have worked very well. Good luck with your entry 6.</td>', 'I like your selection of subject tree, some entries are very uninteresting trees.  I would have preferred a stronger use of the ''rule of 3rds'' and your light is a little off, ie flat.  I can see the trees shadow is long, so you were very close to the right time for perfect light.  On a personal note I would have also liked a bit more saturation in the sky and grass, gold and blue would have worked very well. Good luck with your entry 6.', '2009-01-26 05:20:37.000000', NULL, 1),
(5219511, 758664, 86628, '<td valign="top">You have some very distracting sharpening halos in the upper branches.</td>', 'You have some very distracting sharpening halos in the upper branches.', '2009-01-26 05:54:58.000000', NULL, 1),
(5219538, 759344, 54446, '<td valign="top">Great scene.  Very well composed.  Amazing tonal range.  AA style.  Superb b&amp;w conversion.  My pick for top ribbon in this challenge.   10</td>', 'Great scene.  Very well composed.  Amazing tonal range.  AA style.  Superb b&w conversion.  My pick for top ribbon in this challenge.   10', '2009-01-26 06:26:43.000000', NULL, 1),
(5219540, 757749, 54446, '<td valign="top">Very nice luminous glow through the translucent snow/frost on the tree branches.  Good capture.  A few distracting elements in foreground and sky, but nothing I deducted points for.  9</td>', 'Very nice luminous glow through the translucent snow/frost on the tree branches.  Good capture.  A few distracting elements in foreground and sky, but nothing I deducted points for.  9', '2009-01-26 06:28:28.000000', NULL, 1),
(5219542, 759251, 86628, '<td valign="top">Something weird going on the foreground, nothing is THAT smooth.</td>', 'Something weird going on the foreground, nothing is THAT smooth.', '2009-01-26 06:29:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5219543, 759649, 54446, '<td valign="top">I scored this well.  Good drama and lighting.  The degree of difficulty is different, not necessarily greater, than photographing an outside single tree.  But, I think the uniqueness here is worthy of note.  9</td>', 'I scored this well.  Good drama and lighting.  The degree of difficulty is different, not necessarily greater, than photographing an outside single tree.  But, I think the uniqueness here is worthy of note.  9', '2009-01-26 06:30:48.000000', NULL, 1),
(5219547, 759187, 54446, '<td valign="top">This is excellent.  I understand that you wanted to make the tree look vertically squared to the frame, but you tilted the image to accomplish the look.  (at least that''s my reaction)  Now, I would have accepted the horizon sliding downhill to the right, but it''s the water which betrays.  What a wonderful sky and exposure.  Magnificent colors and amazing dof.  The clipped branches on the right side are a minor distraction.  Should be a ribbon winner, but I can''t say for sure how many will be distracted by the minor landscape issues.  9</td>', 'This is excellent.  I understand that you wanted to make the tree look vertically squared to the frame, but you tilted the image to accomplish the look.  (at least that''s my reaction)  Now, I would have accepted the horizon sliding downhill to the right, but it''s the water which betrays.  What a wonderful sky and exposure.  Magnificent colors and amazing dof.  The clipped branches on the right side are a minor distraction.  Should be a ribbon winner, but I can''t say for sure how many will be distracted by the minor landscape issues.  9', '2009-01-26 06:36:21.000000', NULL, 1),
(5219549, 759446, 54446, '<td valign="top">One of the better images in this challenge.  Mostly, I like the sky gradient from the earth''s shadow.  Well done!  Good detail and exposure of the subject.  The bird is a plus, although that''s unusual in landscape images.  My first reaction to the horizon is that it''s unlevel.  But, could be hill country.  9</td>', 'One of the better images in this challenge.  Mostly, I like the sky gradient from the earth''s shadow.  Well done!  Good detail and exposure of the subject.  The bird is a plus, although that''s unusual in landscape images.  My first reaction to the horizon is that it''s unlevel.  But, could be hill country.  9', '2009-01-26 06:39:16.000000', NULL, 1),
(5219551, 759603, 54446, '<td valign="top">Great detail and tree shape.  Beautiful light and colors.  Wish you had not clipped (minor) the branches on the left and right.  You could have skipped the frame and shown the whole tree to the advantage of the image.  I like this because it shows how the tree has adapted to the prevailing winds or normal storm directions.  8</td>', 'Great detail and tree shape.  Beautiful light and colors.  Wish you had not clipped (minor) the branches on the left and right.  You could have skipped the frame and shown the whole tree to the advantage of the image.  I like this because it shows how the tree has adapted to the prevailing winds or normal storm directions.  8', '2009-01-26 06:42:43.000000', NULL, 1),
(5219552, 758979, 54446, '<td valign="top">Great sky colors.  Exotic (to me) tree.  Superb composition.  Looks like a warm and pleasant place. 8</td>', 'Great sky colors.  Exotic (to me) tree.  Superb composition.  Looks like a warm and pleasant place. 8', '2009-01-26 06:43:46.000000', NULL, 1),
(5219554, 759231, 54446, '<td valign="top">Superb composition.  Amazing detail and exposure.  Beautiful colors. 8</td>', 'Superb composition.  Amazing detail and exposure.  Beautiful colors. 8', '2009-01-26 06:45:53.000000', NULL, 1),
(5219558, 759768, 54446, '<td valign="top">A great sky.  Tree in silhouette top half and in detail below the ridge line, which is how the eye would see it, too, because of the relative brightness of the sky.  Excellent composition and interesting subject.  8</td>', 'A great sky.  Tree in silhouette top half and in detail below the ridge line, which is how the eye would see it, too, because of the relative brightness of the sky.  Excellent composition and interesting subject.  8', '2009-01-26 06:47:59.000000', NULL, 1),
(5219562, 759655, 54446, '<td valign="top">Very pastoral scene. Makes me wish for warmer weather and growing plants.  Nice painterly look.  Too much vignette for me.  Nice s-curve slicing through the pasture.  I might have composed differently, with the tree not so cornered, but the cows are a pleasant element of interest. 8</td>', 'Very pastoral scene. Makes me wish for warmer weather and growing plants.  Nice painterly look.  Too much vignette for me.  Nice s-curve slicing through the pasture.  I might have composed differently, with the tree not so cornered, but the cows are a pleasant element of interest. 8', '2009-01-26 06:51:13.000000', NULL, 1),
(5219564, 759458, 54446, '<td valign="top">Great scene.  Amazing sky.  Very fine tonal range and toning.  Strong composition.  8</td>', 'Great scene.  Amazing sky.  Very fine tonal range and toning.  Strong composition.  8', '2009-01-26 06:53:08.000000', NULL, 1),
(5219577, 759584, 49109, '<td valign="top">nice idea, but not very well executed, lacks of DOF, overall too dark, not enough spice on the "tree"</td>', 'nice idea, but not very well executed, lacks of DOF, overall too dark, not enough spice on the "tree"', '2009-01-26 07:08:30.000000', NULL, 1),
(5219620, 758936, 99218, '<td valign="top">I like this shot!</td>', 'I like this shot!', '2009-01-26 07:53:25.000000', NULL, 1),
(5219621, 758953, 99218, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2009-01-26 07:54:49.000000', NULL, 1),
(5219624, 759395, 76598, '<td valign="top">nice light, love the haze in the background and the strong contrast between the tree limbs and the background</td>', 'nice light, love the haze in the background and the strong contrast between the tree limbs and the background', '2009-01-26 07:58:33.000000', NULL, 1),
(5219625, 758470, 76598, '<td valign="top">cute sign change</td>', 'cute sign change', '2009-01-26 07:58:53.000000', NULL, 1),
(5219627, 759039, 76598, '<td valign="top">I guess it depends on your taste and whether you want an artistic image or a more natural representation....I am too old school</td>', 'I guess it depends on your taste and whether you want an artistic image or a more natural representation....I am too old school', '2009-01-26 07:59:42.000000', NULL, 1),
(5219629, 759327, 99218, '<td valign="top">Great shot!</td>', 'Great shot!', '2009-01-26 07:59:59.000000', NULL, 1),
