(5219631, 759613, 99218, '<td valign="top">Beautiful shot!</td>', 'Beautiful shot!', '2009-01-26 08:00:34.000000', NULL, 1),
(5219633, 758982, 99218, '<td valign="top">Great shot!</td>', 'Great shot!', '2009-01-26 08:01:54.000000', NULL, 1),
(5219635, 759623, 76598, '<td valign="top">I like the stark contrast and the sky banding that leads to the tree....very nice image</td>', 'I like the stark contrast and the sky banding that leads to the tree....very nice image', '2009-01-26 08:02:29.000000', NULL, 1),
(5219636, 759358, 99218, '<td valign="top">Nice Shot!</td>', 'Nice Shot!', '2009-01-26 08:02:38.000000', NULL, 1),
(5219637, 759026, 99218, '<td valign="top">very nicely done!</td>', 'very nicely done!', '2009-01-26 08:03:28.000000', NULL, 1),
(5219638, 759755, 76598, '<td valign="top">nice image, but the title is a stretch</td>', 'nice image, but the title is a stretch', '2009-01-26 08:03:49.000000', NULL, 1),
(5219639, 759655, 99218, '<td valign="top">Great shot!</td>', 'Great shot!', '2009-01-26 08:04:14.000000', NULL, 1),
(5219640, 759182, 76598, '<td valign="top">I like the way the hill leads into the tree, but the shadows really detract from the image</td>', 'I like the way the hill leads into the tree, but the shadows really detract from the image', '2009-01-26 08:04:37.000000', NULL, 1),
(5219641, 759174, 99218, '<td valign="top">well done</td>', 'well done', '2009-01-26 08:04:46.000000', NULL, 1),
(5219644, 758691, 76598, '<td valign="top">very nice image, but there is a lot of urban debris around it</td>', 'very nice image, but there is a lot of urban debris around it', '2009-01-26 08:05:22.000000', NULL, 1),
(5219645, 759254, 99218, '<td valign="top">I like this shot!</td>', 'I like this shot!', '2009-01-26 08:05:38.000000', NULL, 1),
(5219647, 759230, 76598, '<td valign="top">it is too dark to appreciate</td>', 'it is too dark to appreciate', '2009-01-26 08:05:46.000000', NULL, 1),
(5219651, 759403, 76598, '<td valign="top">disorienting at the least</td>', 'disorienting at the least', '2009-01-26 08:09:32.000000', NULL, 1),
(5219653, 759750, 76598, '<td valign="top">the harsh light detracts from the image</td>', 'the harsh light detracts from the image', '2009-01-26 08:11:55.000000', NULL, 1),
(5219679, 759508, 15711, '<td valign="top">Very Zen feeling with the sun (?) - almost like the Japanese flag. I just wish the silhouette was completely focused.</td>', 'Very Zen feeling with the sun (?) - almost like the Japanese flag. I just wish the silhouette was completely focused.', '2009-01-26 08:48:30.000000', NULL, 1),
(5219682, 759521, 15711, '<td valign="top">This is lovely.</td>', 'This is lovely.', '2009-01-26 08:49:07.000000', NULL, 1),
(5219688, 759566, 15711, '<td valign="top">I like how the clouds are creating a V that goes right to the tree. 7</td>', 'I like how the clouds are creating a V that goes right to the tree. 7', '2009-01-26 08:54:21.000000', NULL, 1),
(5219689, 758962, 15711, '<td valign="top">WOW - the sun, birds, a city, a boat AND a tree.  Nice.  If I were to do a thing, I''d not have it cropped so tightly to the tree on the right. I like the diagonal line created, connecting the sun, boat and bench.</td>', 'WOW - the sun, birds, a city, a boat AND a tree.  Nice.  If I were to do a thing, I''d not have it cropped so tightly to the tree on the right. I like the diagonal line created, connecting the sun, boat and bench.', '2009-01-26 08:56:09.000000', NULL, 1),
(5219690, 759017, 15711, '<td valign="top">That sky is spectacular.</td>', 'That sky is spectacular.', '2009-01-26 08:56:26.000000', NULL, 1),
(5219691, 759665, 15711, '<td valign="top">That THAT''s what I''m talkin'' about.  This is just gorgeous.  Everything about this is classic.  Perfect tones, composition and I love that the sun isn''t a giant hot spot, but a beautiful glowing ball of light.  You aced this one. Some might say they want the tree to be tack sharp, but the overall soft feel of this image works great for me. 10</td>', 'That THAT''s what I''m talkin'' about.  This is just gorgeous.  Everything about this is classic.  Perfect tones, composition and I love that the sun isn''t a giant hot spot, but a beautiful glowing ball of light.  You aced this one. Some might say they want the tree to be tack sharp, but the overall soft feel of this image works great for me. 10', '2009-01-26 08:57:53.000000', NULL, 1),
(5219692, 759433, 15711, '<td valign="top">Honestly, what really works for me here is your title.  I love it.</td>', 'Honestly, what really works for me here is your title.  I love it.', '2009-01-26 08:58:45.000000', NULL, 1),
(5219696, 759458, 15711, '<td valign="top">Oh this is stunning. Love the diagonal line of the clouds.  Beautiful.  I love that type of framing, but the harsh white line might be a little more subtle but that''s my taste (I''d run the blur tool across it so that it works more along same feel as the image). 8</td>', 'Oh this is stunning. Love the diagonal line of the clouds.  Beautiful.  I love that type of framing, but the harsh white line might be a little more subtle but that''s my taste (I''d run the blur tool across it so that it works more along same feel as the image). 8', '2009-01-26 09:00:08.000000', NULL, 1),
(5219697, 759275, 15711, '<td valign="top">This has a certain fairy tail quality. Maybe Red Riding Hood is behind that big ol'' tree. :~)</td>', 'This has a certain fairy tail quality. Maybe Red Riding Hood is behind that big ol'' tree. :~)', '2009-01-26 09:00:41.000000', NULL, 1),
(5219698, 759623, 15711, '<td valign="top">I wish the tree''s silhouette were more focused. Love the use of neg. space and how the cloud''s diagonal lines push your eye to the tree.</td>', 'I wish the tree''s silhouette were more focused. Love the use of neg. space and how the cloud''s diagonal lines push your eye to the tree.', '2009-01-26 09:01:15.000000', NULL, 1),
(5219699, 758514, 15711, '<td valign="top">Loving the clouds.  The hint of soft really works.  Loving the blue duotone as well. :~)</td>', 'Loving the clouds.  The hint of soft really works.  Loving the blue duotone as well. :~)', '2009-01-26 09:01:50.000000', NULL, 1),
(5219700, 759671, 15711, '<td valign="top">Great textural and tonal range.</td>', 'Great textural and tonal range.', '2009-01-26 09:02:26.000000', NULL, 1),
(5219702, 759751, 15711, '<td valign="top">That tinge of pink is really pretty.</td>', 'That tinge of pink is really pretty.', '2009-01-26 09:03:20.000000', NULL, 1),
(5219704, 759446, 15711, '<td valign="top">The uneven horizon is a bit distracting for me. :~)</td>', 'The uneven horizon is a bit distracting for me. :~)', '2009-01-26 09:03:41.000000', NULL, 1),
(5219705, 758711, 15711, '<td valign="top">LOL  Love your title.  I wish it weren''t so tightly cropped. :~)</td>', 'LOL  Love your title.  I wish it weren''t so tightly cropped. :~)', '2009-01-26 09:04:17.000000', NULL, 1),
(5219706, 759328, 15711, '<td valign="top">What really works is that vignette/border.  Suits the image. Great use of stark black in the silhouetted scene. I also like that greenish tinge to the duotone.</td>', 'What really works is that vignette/border.  Suits the image. Great use of stark black in the silhouetted scene. I also like that greenish tinge to the duotone.', '2009-01-26 09:05:42.000000', NULL, 1),
(5219708, 759637, 15711, '<td valign="top">Oh that is interesting. I like it. The sky is almost like an old rusty sheet of metal.  Different :~J</td>', 'Oh that is interesting. I like it. The sky is almost like an old rusty sheet of metal.  Different :~J', '2009-01-26 09:06:33.000000', NULL, 1),
(5219710, 759095, 15711, '<td valign="top">What a great old tree.  Wish it weren''t so boxed in. I''d have more negative space around it. :~)</td>', 'What a great old tree.  Wish it weren''t so boxed in. I''d have more negative space around it. :~)', '2009-01-26 09:07:37.000000', NULL, 1),
(5219711, 758327, 15711, '<td valign="top">WOW that is terrific balance.  I think a bit of levels adjustment would really enhance the various shades of gray. :~)</td>', 'WOW that is terrific balance.  I think a bit of levels adjustment would really enhance the various shades of gray. :~)', '2009-01-26 09:08:03.000000', NULL, 1),
(5219712, 759343, 15711, '<td valign="top">Just stunning.  I love the hint of softness.  This is MY kind of shot. :~) 8</td>', 'Just stunning.  I love the hint of softness.  This is MY kind of shot. :~) 8', '2009-01-26 09:08:20.000000', NULL, 1),
(5219713, 758936, 15711, '<td valign="top">I like how the road bends our eye around that tree and back to the two in the background. I like the sun behind the clouds too.  This is nicely composed.  I wonder if some will detract because of the other two in the background. I hope not. This is nice. :~)</td>', 'I like how the road bends our eye around that tree and back to the two in the background. I like the sun behind the clouds too.  This is nicely composed.  I wonder if some will detract because of the other two in the background. I hope not. This is nice. :~)', '2009-01-26 09:09:19.000000', NULL, 1),
(5219714, 759769, 15711, '<td valign="top">I really like the composition. Not sure about the vignette though. Hmmmm :~)</td>', 'I really like the composition. Not sure about the vignette though. Hmmmm :~)', '2009-01-26 09:10:00.000000', NULL, 1),
(5219716, 757839, 15711, '<td valign="top">I like the stark white background and the textures of the little sapling. The worms. LOL  Reminds me of my Earth Day image I did in 2008. :~)<a href="//www.dpchallenge.com/image.php?IMAGE_ID=671920" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/15000-19999/15711/120/671920.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/15000-19999/15711/120/671920.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/15000-19999/15711/120/671920.jpg"/></a></td>', 'I like the stark white background and the textures of the little sapling. The worms. LOL  Reminds me of my Earth Day image I did in 2008. :~)', '2009-01-26 09:12:11.000000', NULL, 1),
(5219717, 759764, 15711, '<td valign="top">Don''t you just love those clouds???</td>', 'Don''t you just love those clouds???', '2009-01-26 09:12:33.000000', NULL, 1),
(5219719, 759344, 15711, '<td valign="top">WOW - very Ansel Adams.  I like the composition.  If it were mine, I might''ve done a bit of burn on the rocks, to distinguish some of the tonal variances of them. :~)</td>', 'WOW - very Ansel Adams.  I like the composition.  If it were mine, I might''ve done a bit of burn on the rocks, to distinguish some of the tonal variances of them. :~)', '2009-01-26 09:13:59.000000', NULL, 1),
(5219720, 759603, 15711, '<td valign="top">Nice "fill the frame" without it feeling too boxed in. I like the complimentary blue/brown duotone.  Nice.</td>', 'Nice "fill the frame" without it feeling too boxed in. I like the complimentary blue/brown duotone.  Nice.', '2009-01-26 09:14:58.000000', NULL, 1),
(5219722, 759507, 15711, '<td valign="top">Great composition.  My only nitpick is the lack of contrasts in the tones (brighter highlights and darker shadows).  Just my taste. :~)</td>', 'Great composition.  My only nitpick is the lack of contrasts in the tones (brighter highlights and darker shadows).  Just my taste. :~)', '2009-01-26 09:16:03.000000', NULL, 1),
(5219723, 759231, 15711, '<td valign="top">Beautiful colors.  Very majestic.</td>', 'Beautiful colors.  Very majestic.', '2009-01-26 09:16:32.000000', NULL, 1),
(5219725, 759174, 15711, '<td valign="top">Love the texture of the rocks.  WOW - what a vista.  This is beautiful. 8</td>', 'Love the texture of the rocks.  WOW - what a vista.  This is beautiful. 8', '2009-01-26 09:17:03.000000', NULL, 1),
(5219726, 757950, 15711, '<td valign="top">I like it but wish it weren''t so tightly cropped.</td>', 'I like it but wish it weren''t so tightly cropped.', '2009-01-26 09:18:25.000000', NULL, 1),
(5219727, 759249, 15711, '<td valign="top">Oh I like this a lot.  The line of the hill is a nice tough.  Beautiful colors.</td>', 'Oh I like this a lot.  The line of the hill is a nice tough.  Beautiful colors.', '2009-01-26 09:18:51.000000', NULL, 1),
(5219728, 758957, 15711, '<td valign="top">I might up the shadow tones to make them more stark against the white. :~) I like the compositoin.</td>', 'I might up the shadow tones to make them more stark against the white. :~) I like the compositoin.', '2009-01-26 09:19:23.000000', NULL, 1),
(5219730, 759358, 15711, '<td valign="top">So pretty. Love the line of the little creek. Beautiful textural range too.</td>', 'So pretty. Love the line of the little creek. Beautiful textural range too.', '2009-01-26 09:20:28.000000', NULL, 1),
(5219731, 759720, 15711, '<td valign="top">Love the colors.  Not so sure about the tilt. :~)</td>', 'Love the colors.  Not so sure about the tilt. :~)', '2009-01-26 09:21:25.000000', NULL, 1),
(5219733, 759729, 15711, '<td valign="top">That is VERY striking.  Really nice. I like the sharpness of the tree''s silhouette against those clouds.  This would make a great print. :~) 8</td>', 'That is VERY striking.  Really nice. I like the sharpness of the tree''s silhouette against those clouds.  This would make a great print. :~) 8', '2009-01-26 09:22:26.000000', NULL, 1),
(5219734, 759653, 15711, '<td valign="top">Nice inclusion of the person and the bike.  I think this is really striking. :~) 8</td>', 'Nice inclusion of the person and the bike.  I think this is really striking. :~) 8', '2009-01-26 09:23:01.000000', NULL, 1),
(5219735, 759368, 15711, '<td valign="top">LOVE THAT!!!</td>', 'LOVE THAT!!!', '2009-01-26 09:23:20.000000', NULL, 1),
(5219737, 759402, 15711, '<td valign="top">Beautiful colors and shadows.  The sun is a touch hot (well, duh) but I like it. 8</td>', 'Beautiful colors and shadows.  The sun is a touch hot (well, duh) but I like it. 8', '2009-01-26 09:23:55.000000', NULL, 1),
(5219739, 759739, 15711, '<td valign="top">The foreground and tree seem a touch oversharp. Love the composition and the juxtaposition between the tree and clouds.</td>', 'The foreground and tree seem a touch oversharp. Love the composition and the juxtaposition between the tree and clouds.', '2009-01-26 09:25:01.000000', NULL, 1),
(5219740, 758978, 15711, '<td valign="top">This is lovely.  So simple. :~)</td>', 'This is lovely.  So simple. :~)', '2009-01-26 09:25:20.000000', NULL, 1),
(5219741, 759250, 15711, '<td valign="top">Nice.  To my eye, I''d crop more from the right but it''s great. 7</td>', 'Nice.  To my eye, I''d crop more from the right but it''s great. 7', '2009-01-26 09:26:00.000000', NULL, 1),
(5219748, 759767, 35947, '<td valign="top">The sky looks so unusual here, a little unnatural.</td>', 'The sky looks so unusual here, a little unnatural.', '2009-01-26 09:33:48.000000', NULL, 1),
(5219749, 758327, 35947, '<td valign="top">Great capture!  Wish the focus was a little stronger.</td>', 'Great capture!  Wish the focus was a little stronger.', '2009-01-26 09:34:06.000000', NULL, 1),
