(5221782, 759106, 56275, '<td valign="top">Love the colors in this shot. And the curved horizon gives the shot a neat earthy-globe feel.</td>', 'Love the colors in this shot. And the curved horizon gives the shot a neat earthy-globe feel.', '2009-01-27 10:05:15.000000', NULL, 1),
