(5233996, 758953, 83313, '<td valign="top">Nice use of tones, especially well done since this appears to be shot in midday sun.</td>', 'Nice use of tones, especially well done since this appears to be shot in midday sun.', '2009-02-01 23:44:00.000000', NULL, 1),
(5234001, 759720, 83313, '<td valign="top">The tilt doesn''t come off right to me, otherwise I like the colors and tones here.</td>', 'The tilt doesn''t come off right to me, otherwise I like the colors and tones here.', '2009-02-01 23:45:08.000000', NULL, 1),
(5234003, 759565, 30364, '<td valign="top">There''s something very moving about this.  Maybe it''s the fact that the tree appears hacked off on one side, which seems to emphasise the merciless nature of this place.  The fact that it''s not rendered in improbably sharp detail helps of course.  7.</td>', 'There''s something very moving about this.  Maybe it''s the fact that the tree appears hacked off on one side, which seems to emphasise the merciless nature of this place.  The fact that it''s not rendered in improbably sharp detail helps of course.  7.', '2009-02-01 23:45:42.000000', NULL, 1),
(5234004, 759026, 79847, '<td valign="top">Awesome photo, hope no-one was effected by this flood too much. 9</td>', 'Awesome photo, hope no-one was effected by this flood too much. 9', '2009-02-01 23:46:04.000000', NULL, 1),
(5234006, 759510, 83313, '<td valign="top">Heavy JPEG compression is killing a lot of detail for you. It''s a great scene, but comes across very coarse. I can especially see some compression artifacts around the top of the tree and the horizon.</td>', 'Heavy JPEG compression is killing a lot of detail for you. It''s a great scene, but comes across very coarse. I can especially see some compression artifacts around the top of the tree and the horizon.', '2009-02-01 23:46:39.000000', NULL, 1),
(5234008, 759394, 30364, '<td valign="top">One of the best uses I''ve seen of this kind of vignette effect.  It seems to understand the tree, and because of it, so do I.  8.</td>', 'One of the best uses I''ve seen of this kind of vignette effect.  It seems to understand the tree, and because of it, so do I.  8.', '2009-02-01 23:46:51.000000', NULL, 1),
(5234009, 758711, 83313, '<td valign="top">Almost looks like a painting. Nice use of the usually dull winter colors.</td>', 'Almost looks like a painting. Nice use of the usually dull winter colors.', '2009-02-01 23:47:16.000000', NULL, 1),
(5234016, 759653, 83313, '<td valign="top">Oh heck, it''s got a bicycle in it. Looks like she has been out on her bike exploring the countryside. Well, I won''t be the first person to have personal preference influence his vote some. Even without the bike, it''s a very nice shot. 7 and a fave.</td>', 'Oh heck, it''s got a bicycle in it. Looks like she has been out on her bike exploring the countryside. Well, I won''t be the first person to have personal preference influence his vote some. Even without the bike, it''s a very nice shot. 7 and a fave.', '2009-02-01 23:49:41.000000', NULL, 1),
(5234017, 758372, 30364, '<td valign="top">This will not score well I suppose, but I think it''s really very clever and thoughtful too.  The tree is indeed stuck among all these non-trees, and yet still competes for life even against the inanimate pretenders.  It''s probably losing, alas.  9.</td>', 'This will not score well I suppose, but I think it''s really very clever and thoughtful too.  The tree is indeed stuck among all these non-trees, and yet still competes for life even against the inanimate pretenders.  It''s probably losing, alas.  9.', '2009-02-01 23:50:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5234018, 758520, 88136, '<td valign="top">hmm. what an unusual tree</td>', 'hmm. what an unusual tree', '2009-02-01 23:50:39.000000', NULL, 1),
(5234019, 759677, 83313, '<td valign="top">Banyan vines. Makes me think of networks. I''m such a geek.</td>', 'Banyan vines. Makes me think of networks. I''m such a geek.', '2009-02-01 23:51:01.000000', NULL, 1),
(5234020, 759760, 30364, '<td valign="top">The most interesting in the challenge just because of the inspired juxtaposition.  10.</td>', 'The most interesting in the challenge just because of the inspired juxtaposition.  10.', '2009-02-01 23:52:03.000000', NULL, 1),
(5234021, 759176, 83313, '<td valign="top">Looks like an illustration from a children''s book. Appears a bit pixelated in the brightest area.</td>', 'Looks like an illustration from a children''s book. Appears a bit pixelated in the brightest area.', '2009-02-01 23:52:26.000000', NULL, 1),
(5234022, 759187, 88136, '<td valign="top">love your horizen. yeh fight the man! lol. beautiful scene</td>', 'love your horizen. yeh fight the man! lol. beautiful scene', '2009-02-01 23:52:33.000000', NULL, 1),
(5234023, 759288, 88136, '<td valign="top">i would love to be buried in a place like this. its just beautiful</td>', 'i would love to be buried in a place like this. its just beautiful', '2009-02-01 23:52:51.000000', NULL, 1),
(5234024, 759039, 83313, '<td valign="top">Very soft, but also very moody and subtle. I think this may be one of the underrated shots in this challenge. We''ll know in 7 minutes.</td>', 'Very soft, but also very moody and subtle. I think this may be one of the underrated shots in this challenge. We''ll know in 7 minutes.', '2009-02-01 23:53:54.000000', NULL, 1),
(5234025, 757839, 88136, '<td valign="top">oh i love it! excellent</td>', 'oh i love it! excellent', '2009-02-01 23:54:12.000000', NULL, 1),
(5234026, 758597, 83313, '<td valign="top">Nice try, throwing that flare into the title. I like it in spite of the flare.</td>', 'Nice try, throwing that flare into the title. I like it in spite of the flare.', '2009-02-01 23:55:49.000000', NULL, 1),
(5234030, 759620, 30364, '<td valign="top">Very fine photograph.  What''s so very good about it is that you knew that the tree could not, should not, be made into a ''hero'' in this photograph.  It''s nearly buried here, nearly overwhelmed, and that''s the majesty of it ... that it has insisted on remaining a tree, and a proper one, even against this level of affront.  The birds appreciate it, and so did you.  Me too.  10</td>', 'Very fine photograph.  What''s so very good about it is that you knew that the tree could not, should not, be made into a ''hero'' in this photograph.  It''s nearly buried here, nearly overwhelmed, and that''s the majesty of it ... that it has insisted on remaining a tree, and a proper one, even against this level of affront.  The birds appreciate it, and so did you.  Me too.  10', '2009-02-01 23:57:06.000000', NULL, 1),
(5234031, 759350, 83313, '<td valign="top">Colors come off a bit dull and low contrast. Has some potential that I think some adjustments could bring out.</td>', 'Colors come off a bit dull and low contrast. Has some potential that I think some adjustments could bring out.', '2009-02-01 23:57:31.000000', NULL, 1),
(5234032, 758654, 83313, '<td valign="top">A different approach that I like.</td>', 'A different approach that I like.', '2009-02-01 23:58:01.000000', NULL, 1),
(5234033, 759505, 30364, '<td valign="top">I think this is really quite lovely.  It''s not the flashiest shot here, very quiet and composed (pun intended), but certainly not diminished by any of that understatement.  The pairing of the tree with the bench is very thoughtful, and the photograph works so much better with the bench empty.  Just imagine a person sitting there ... the photograph would no longer be about the tree, whereas this way it unequivocally is; the bench is just a sidekick, but a sidekick that lends the tree both scale and purpose.  I had it at 7 until it slowly dawned on me how very good it is, so now it''s 9.  Thanks for thinking.</td>', 'I think this is really quite lovely.  It''s not the flashiest shot here, very quiet and composed (pun intended), but certainly not diminished by any of that understatement.  The pairing of the tree with the bench is very thoughtful, and the photograph works so much better with the bench empty.  Just imagine a person sitting there ... the photograph would no longer be about the tree, whereas this way it unequivocally is; the bench is just a sidekick, but a sidekick that lends the tree both scale and purpose.  I had it at 7 until it slowly dawned on me how very good it is, so now it''s 9.  Thanks for thinking.', '2009-02-01 23:58:23.000000', NULL, 1),
(5234035, 759727, 24486, '<td valign="top">A novel twist on the theme. Having the boy does add perspective to just how big that tree is. I rather like your lighting on this photograph.</td>', 'A novel twist on the theme. Having the boy does add perspective to just how big that tree is. I rather like your lighting on this photograph.', '2009-02-01 23:59:06.000000', NULL, 1),
(5234038, 758936, 50641, '<td valign="top">Congrats on the ribbon and the 1x pub!  Love the colors here although it looked great monotone too!</td>', 'Congrats on the ribbon and the 1x pub!  Love the colors here although it looked great monotone too!', '2009-02-02 00:03:18.000000', NULL, 0),
(5234040, 758936, 30364, '<td valign="top">I didn''t give it a 3!!!!</td>', 'I didn''t give it a 3!!!!', '2009-02-02 00:04:32.000000', NULL, 0),
(5234043, 758936, 32872, '<td valign="top">CONGRATS Deb!!!!!  A well-deserved ribbon for such a lovely image!</td>', 'CONGRATS Deb!!!!!  A well-deserved ribbon for such a lovely image!', '2009-02-02 00:05:03.000000', NULL, 0),
(5234044, 759251, 50641, '<td valign="top">So clean and silvery!  Very elegant.  Congrats on the nice placement!</td>', 'So clean and silvery!  Very elegant.  Congrats on the nice placement!', '2009-02-02 00:05:18.000000', NULL, 0),
(5234047, 759174, 98771, '<td valign="top">WOW, that''s all I can think to say. Oh yes, and congratulations.<br/> <br/>Mac,</td>', 'WOW, that''s all I can think to say. Oh yes, and congratulations. Mac,', '2009-02-02 00:05:54.000000', NULL, 0),
(5234048, 758936, 62357, '<td valign="top">Wow Deb.  I really liked this one, guess I wasn''t alone.  Well done on such an awesome result</td>', 'Wow Deb.  I really liked this one, guess I wasn''t alone.  Well done on such an awesome result', '2009-02-02 00:06:09.000000', NULL, 0),
(5234051, 758936, 67697, '<td valign="top">I like the two little trees kind of hanging back and looking at the big one in the foreground.  Great job with the editing - I like how you highlighted the walking path.  Congrats on the ribbon!!!</td>', 'I like the two little trees kind of hanging back and looking at the big one in the foreground.  Great job with the editing - I like how you highlighted the walking path.  Congrats on the ribbon!!!', '2009-02-02 00:06:38.000000', NULL, 0),
(5234052, 758936, 45475, '<td valign="top">Congratulations Deb! This really is a pleasure to view. Magic light!</td>', 'Congratulations Deb! This really is a pleasure to view. Magic light!', '2009-02-02 00:07:05.000000', NULL, 0),
(5234057, 759174, 102024, '<td valign="top">I had a hunch this would win.  Congratulations!</td>', 'I had a hunch this would win.  Congratulations!', '2009-02-02 00:10:17.000000', NULL, 0),
(5234060, 758936, 22537, '<td valign="top">Beautiful image. Congrats on the red.</td>', 'Beautiful image. Congrats on the red.', '2009-02-02 00:11:15.000000', NULL, 0),
(5234064, 757985, 69046, '<td valign="top">I don''t get it. This is awesome.</td>', 'I don''t get it. This is awesome.', '2009-02-02 00:12:31.000000', NULL, 0),
(5234067, 758936, 96751, '<td valign="top">This image clearly left me speechless, as evidenced by my cryptic message...  Meant to say, gorgeous shot.  Love that the fog filtered out the sun to a little bright dot.  Wonderful detail in spite of the lighting.  Love the tones.  Congrats on a fabulous and deserving winner.</td>', 'This image clearly left me speechless, as evidenced by my cryptic message...  Meant to say, gorgeous shot.  Love that the fog filtered out the sun to a little bright dot.  Wonderful detail in spite of the lighting.  Love the tones.  Congrats on a fabulous and deserving winner.', '2009-02-02 00:12:55.000000', NULL, 0),
(5234070, 758936, 79602, '<td valign="top">WTG Deb!!!  Love it!</td>', 'WTG Deb!!!  Love it!', '2009-02-02 00:13:40.000000', NULL, 0),
(5234075, 759174, 101117, '<td valign="top">Well deserved first place, in such a mundane challenge you managed to pull of an exceptionally good shot!</td>', 'Well deserved first place, in such a mundane challenge you managed to pull of an exceptionally good shot!', '2009-02-02 00:16:38.000000', NULL, 0),
(5234077, 758936, 79955, '<td valign="top">Woohoo! Deb, Congrats - beautiful , well done</td>', 'Woohoo! Deb, Congrats - beautiful , well done', '2009-02-02 00:16:48.000000', NULL, 0),
(5234079, 758936, 83313, '<td valign="top">I gave it a 7. Great use of the overcast sky and a strong perspective view. Congrats on another ribbon.</td>', 'I gave it a 7. Great use of the overcast sky and a strong perspective view. Congrats on another ribbon.', '2009-02-02 00:16:52.000000', NULL, 0),
(5234080, 759251, 86447, '<td valign="top">OH so close to a Top TEn... *sigh*<br/>  Good score though!  Yippee!</td>', 'OH so close to a Top TEn... *sigh*  Good score though!  Yippee!', '2009-02-02 00:17:33.000000', NULL, 0),
(5234086, 759174, 30454, '<td valign="top">Well deserved first place. Congratulations!!</td>', 'Well deserved first place. Congratulations!!', '2009-02-02 00:18:41.000000', NULL, 0),
(5234090, 758936, 30454, '<td valign="top">Congrats, I really liked this one. I am happy it got a ribbon.</td>', 'Congrats, I really liked this one. I am happy it got a ribbon.', '2009-02-02 00:20:10.000000', NULL, 0),
(5234092, 758936, 30861, '<td valign="top">WTG Deb! *Love* the tiny disk of sun in this :-)</td>', 'WTG Deb! *Love* the tiny disk of sun in this :-)', '2009-02-02 00:20:54.000000', NULL, 0),
(5234094, 759402, 30454, '<td valign="top">This was my top score. I knew this will ribbon. Excellent photo indeed.</td>', 'This was my top score. I knew this will ribbon. Excellent photo indeed.', '2009-02-02 00:21:17.000000', NULL, 0),
(5234095, 758936, 98771, '<td valign="top">Congratulations, this is really nice.<br/> <br/>Mac,</td>', 'Congratulations, this is really nice. Mac,', '2009-02-02 00:21:19.000000', NULL, 0),
(5234100, 759402, 98771, '<td valign="top">Congrats on the ribbon, nice image.</td>', 'Congrats on the ribbon, nice image.', '2009-02-02 00:22:37.000000', NULL, 0),
(5234102, 759671, 30454, '<td valign="top">Very powerful B&amp;W image. Congrats on HM.</td>', 'Very powerful B&W image. Congrats on HM.', '2009-02-02 00:23:29.000000', NULL, 0),
(5234105, 759402, 30982, '<td valign="top">Two German trees on the front page!  :-)  Congrats!  Back to add that I really love the long shadows - of the tree and the dog and his man - and the bits of city beyond.  Feels warm and inviting, even though I know it''s been quite cold lately!  A lovely, pleasing evening walk captured!<br/><br/><i>Message edited by author 2009-02-02 03:15:40.</i></td>', 'Two German trees on the front page!  :-)  Congrats!  Back to add that I really love the long shadows - of the tree and the dog and his man - and the bits of city beyond.  Feels warm and inviting, even though I know it''s been quite cold lately!  A lovely, pleasing evening walk captured!', '2009-02-02 00:23:51.000000', '2009-02-02 03:15:40.000000', 0),
(5234111, 759433, 42091, '<td valign="top">Thank you for your votes and comments.  This is my personal best!<br/> <br/>This young oak tree lives along my puppy''s and my walking path.  It has been very tenacious in holding on to its leaves which turned a bright red in the fall.  I was suprised how little ''photoshopping'' was required to restore nearly original fall color.<br/> <br/>I considered cloning out the second (''companion'') tree - which a number of you suggested - but the little red tree appeared lonely and I convinced myself (wrongly perhaps?) that the companion tree is consistent with the title.<br/> <br/>Thank you again...<br/><br/><i>Message edited by author 2009-02-02 08:11:25.</i></td>', 'Thank you for your votes and comments.  This is my personal best! This young oak tree lives along my puppy''s and my walking path.  It has been very tenacious in holding on to its leaves which turned a bright red in the fall.  I was suprised how little ''photoshopping'' was required to restore nearly original fall color. I considered cloning out the second (''companion'') tree - which a number of you suggested - but the little red tree appeared lonely and I convinced myself (wrongly perhaps?) that the companion tree is consistent with the title. Thank you again...', '2009-02-02 00:25:21.000000', '2009-02-02 08:11:25.000000', 0),
(5234118, 759762, 49954, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by DigiFotoBuddy:</b></div><hr/><i> Yes, it''s good out of the box concept for tree challenge. But still "too much" out of the box for me when chellenge description clearly said shoot a single tree. </i></td></tr></table> <br/> <br/>How is it both a good out of the box concept AND "too much" out of the box.<br/> <br/>As you said, "chellenge description clearly said shoot a single tree."  -- This does that completely.</td>', 'Originally posted by DigiFotoBuddy: Yes, it''s good out of the box concept for tree challenge. But still "too much" out of the box for me when chellenge description clearly said shoot a single tree.   How is it both a good out of the box concept AND "too much" out of the box. As you said, "chellenge description clearly said shoot a single tree."  -- This does that completely.', '2009-02-02 00:27:37.000000', NULL, 0),
(5234119, 758936, 36619, '<td valign="top">beautiful job!</td>', 'beautiful job!', '2009-02-02 00:27:56.000000', NULL, 0),
(5234129, 758699, 30861, '<td valign="top">Hah, might have known this was yours :-) I''m your 8, friend. I think this is a heck of a nice shot, sigh. Congrats on your brown!</td>', 'Hah, might have known this was yours :-) I''m your 8, friend. I think this is a heck of a nice shot, sigh. Congrats on your brown!', '2009-02-02 00:29:34.000000', NULL, 0),
(5234135, 758470, 30861, '<td valign="top">Hrmmm... I can understand this not placing, of course, but 135th? For an image that''s amusing, a little thought-provoking, and represents a unique take on the challenge that is unarguably MEETING the challenge? Pffft!</td>', 'Hrmmm... I can understand this not placing, of course, but 135th? For an image that''s amusing, a little thought-provoking, and represents a unique take on the challenge that is unarguably MEETING the challenge? Pffft!', '2009-02-02 00:32:05.000000', NULL, 0),
(5234138, 759231, 30861, '<td valign="top">I''m one of your 9''s, Judi. I really, really like this. I hope you''ll post the original for us, I''d like to see where this came from. The quality of light on the tree trunk is quite ethereal.</td>', 'I''m one of your 9''s, Judi. I really, really like this. I hope you''ll post the original for us, I''d like to see where this came from. The quality of light on the tree trunk is quite ethereal.', '2009-02-02 00:33:46.000000', NULL, 0),
(5234141, 759762, 83313, '<td valign="top">It didn''t come up for me in voting, and I really don''t know how I would have gone if it had come up. I think I would have considered it for a few minutes and then gone back and re-read the challenge description. Of course, hindsight is 20/20 and I really don''t know for sure how I would have gone. My wife is into genealogy, so I prefer to think I woudl have recognized it as fitting.  A good entry and very out of the box.</td>', 'It didn''t come up for me in voting, and I really don''t know how I would have gone if it had come up. I think I would have considered it for a few minutes and then gone back and re-read the challenge description. Of course, hindsight is 20/20 and I really don''t know for sure how I would have gone. My wife is into genealogy, so I prefer to think I woudl have recognized it as fitting.  A good entry and very out of the box.', '2009-02-02 00:35:19.000000', NULL, 0),
(5234145, 759755, 3724, '<td valign="top">I like the seemingly improbable location for this - 8</td>', 'I like the seemingly improbable location for this - 8', '2009-02-02 00:36:01.000000', NULL, 0),
(5234146, 759343, 30861, '<td valign="top">This is the highest finisher of the 8''s I awarded. I like the almost-ethereal quality of "soft sharpness" you''ve captured here. The only nit I have with the image, what kept it from a 9 in my book, is the vague, diffuse haloing around the tree. Congrats on a very fine image.</td>', 'This is the highest finisher of the 8''s I awarded. I like the almost-ethereal quality of "soft sharpness" you''ve captured here. The only nit I have with the image, what kept it from a 9 in my book, is the vague, diffuse haloing around the tree. Congrats on a very fine image.', '2009-02-02 00:36:13.000000', NULL, 0),
(5234147, 759637, 24389, '<td valign="top">pretty colors :)</td>', 'pretty colors :)', '2009-02-02 00:36:38.000000', NULL, 0),
(5234149, 758111, 30861, '<td valign="top">Really nicely seen and rendered, Beetle. One of my 8''s. I particularly applaud your willingess to let the bright part of the sky blow out; it seems very real to me.</td>', 'Really nicely seen and rendered, Beetle. One of my 8''s. I particularly applaud your willingess to let the bright part of the sky blow out; it seems very real to me.', '2009-02-02 00:37:35.000000', NULL, 0),
(5234151, 758699, 83313, '<td valign="top">Can I congratulate you on your "ribbon"?</td>', 'Can I congratulate you on your "ribbon"?', '2009-02-02 00:38:00.000000', NULL, 0),
(5234158, 759174, 79847, '<td valign="top">Congrats, this was my favourite.  Glad to see you get top ribbon.</td>', 'Congrats, this was my favourite.  Glad to see you get top ribbon.', '2009-02-02 00:39:12.000000', NULL, 0),
(5234162, 758372, 30861, '<td valign="top">Another of my 8''s  I gave 8''s to both this one and the Brown Ribbon :-) I''m intrigued that Ubique and I both have exactly the same reaction to your image. It''s a pity so few are willing to absorb this sort of image and let it speak to them from the photographer''s heart. Wonderful shot, well done!</td>', 'Another of my 8''s  I gave 8''s to both this one and the Brown Ribbon :-) I''m intrigued that Ubique and I both have exactly the same reaction to your image. It''s a pity so few are willing to absorb this sort of image and let it speak to them from the photographer''s heart. Wonderful shot, well done!', '2009-02-02 00:40:04.000000', NULL, 0),
(5234175, 759551, 30861, '<td valign="top">Nice finish, <strike>Dick</strike> Richard! I love the title, and I like the way you''ve chosen to render the scene. I''m curious to see you''re calling this a Ponderosa. I don''t doubt that you''re right (you live there after all, you *should* know, and I''m sure you do) but every Ponderosa *I''ve* ever seen, or heard of, is very tall and very straight of trunk... Is this a different variety of the family, or have I just been blinded by stereotype?<br/> <br/>Regardless, congrats on your top 10!<br/><br/><i>Message edited by author 2017-08-31 23:18:29.</i></td>', 'Nice finish, Dick Richard! I love the title, and I like the way you''ve chosen to render the scene. I''m curious to see you''re calling this a Ponderosa. I don''t doubt that you''re right (you live there after all, you *should* know, and I''m sure you do) but every Ponderosa *I''ve* ever seen, or heard of, is very tall and very straight of trunk... Is this a different variety of the family, or have I just been blinded by stereotype? Regardless, congrats on your top 10!', '2009-02-02 00:44:45.000000', '2017-09-01 00:18:29.000000', 0),
(5234184, 759668, 3724, '<td valign="top">nice strong tone.</td>', 'nice strong tone.', '2009-02-02 00:47:43.000000', NULL, 0),
(5234187, 759174, 52549, '<td valign="top">Stunning image. Huge congrats on your Blue, Paulo.</td>', 'Stunning image. Huge congrats on your Blue, Paulo.', '2009-02-02 00:48:11.000000', NULL, 0),
(5234190, 758936, 52549, '<td valign="top">WTB, Deb! Beautiful and moody looking shot. Love the "parents" along the road, too. Congrats on your ribon.</td>', 'WTB, Deb! Beautiful and moody looking shot. Love the "parents" along the road, too. Congrats on your ribon.', '2009-02-02 00:50:41.000000', NULL, 0),
(5234192, 759402, 52549, '<td valign="top">Great shot, Christiane. Congratulations on your ribbon and a big ((hug)) from me.</td>', 'Great shot, Christiane. Congratulations on your ribbon and a big ((hug)) from me.', '2009-02-02 00:52:08.000000', NULL, 0),
(5234198, 758936, 44877, '<td valign="top">Woohoo Deb!! Congrats - that''s awesome! What a beautiful photo. <br/> <br/></td>', 'Woohoo Deb!! Congrats - that''s awesome! What a beautiful photo.  ', '2009-02-02 00:55:41.000000', NULL, 0),
(5234199, 759368, 52549, '<td valign="top">On the contrary, I think it''s very eye-catching ;-) The simplicity and the muted colours make it one of the best in this challenge for me. Good one, MAK. Congrats on top 10.</td>', 'On the contrary, I think it''s very eye-catching ;-) The simplicity and the muted colours make it one of the best in this challenge for me. Good one, MAK. Congrats on top 10.', '2009-02-02 00:55:44.000000', NULL, 0),
