(5238059, 759174, 102655, '<td valign="top">i love this photo - great play on words in the title as well<br/>:)</td>', 'i love this photo - great play on words in the title as well:)', '2009-02-03 23:33:07.000000', NULL, 0),
(5238156, 758936, 54645, '<td valign="top">Deb, strong work. I commented on the less colorful version.</td>', 'Deb, strong work. I commented on the less colorful version.', '2009-02-04 00:13:06.000000', NULL, 0),
(5238435, 759174, 45621, '<td valign="top">Somehow i really feel that a 1:2 crop will give the tree more prominence. Nevertheless, what a great shot! the colours and contrast bring out the dramatic clouds and textured rocks so much more. EXCELLENT!</td>', 'Somehow i really feel that a 1:2 crop will give the tree more prominence. Nevertheless, what a great shot! the colours and contrast bring out the dramatic clouds and textured rocks so much more. EXCELLENT!', '2009-02-04 03:02:21.000000', NULL, 0),
(5238482, 758699, 102925, '<td valign="top">It''s a real shame this rated so low as it''s quite beautiful.<br/>Sure it''s not the usual winning formula but well done for submitting something so different from everything else. My hat goes off to you.</td>', 'It''s a real shame this rated so low as it''s quite beautiful.Sure it''s not the usual winning formula but well done for submitting something so different from everything else. My hat goes off to you.', '2009-02-04 03:43:43.000000', NULL, 0),
